  class LucideIcon extends HTMLElement {
    static get observedAttributes() { return ['name']; }
    connectedCallback() { this.render(); }
    attributeChangedCallback() { if (this.isConnected) this.render(); }
    render() {
      var raw = this.getAttribute('name') || '';
      var key = ICONS[raw] ? raw : ALIASES[raw];
      var body = key && ICONS[key];
      if (!body) {
        this.textContent = '';
        if (raw && window.console) console.warn('lucide-icon: no icon for "' + raw + '"');
        return;
      }
      this.innerHTML = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="' +
        (this.getAttribute('stroke-width') || '2') + '" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false">' + body + '</svg>';
    }
  }

  customElements.define('lucide-icon', LucideIcon);
